const page = new Page();
await page.goto("http://127.0.0.1:3002/login");
page.fill("input[name=\"username\"]", "$LP_STORE_USERNAME");
page.fill("input[name=\"password\"]", "$LP_STORE_PASSWORD");
const clicked = page.click("form[action=\"/login\"] button[type=\"submit\"]");
const afterClickUrl = page.evaluate("location.href");
const waited = page.waitForSelector("form[action=\"/inventory\"]");
const field = "input[name=\"available-KC-ETH-200\"]";
const before = page.extract({ attr: { selector: field, attr: "value" }, matches: [field] });
const filled = page.fill(field, "6");
const after = page.extract({ attr: { selector: field, attr: "value" } });
const property = page.evaluate(`document.querySelector(${JSON.stringify(field)}).value`);
const label = page.extract({ save: "button[name=\"action\"][value=\"save\"]" });
const none = (() => { try { return page.extract({ matches: ["button.nope"] }); } catch (error) { return String(error); } })();
console.log("console line");
console.warn("warn line");
return { clicked, afterClickUrl, waited, before, filled, after, property, propertyType: typeof property, label, none };

